import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';

export async function gate({ referenceDir, submissionDir }) {
  try {
    const submissionFile = path.join(submissionDir, 'answer.mjs');
    const pinnedFile = path.join(referenceDir, 'pinned-test-cases.txt');
    if (!fs.existsSync(submissionFile)) return { accept: false, reason: 'missing answer.mjs' };
    if (!fs.existsSync(pinnedFile)) return { accept: false, reason: 'missing pinned-test-cases.txt' };
    const pinned = fs.readFileSync(pinnedFile, 'utf8');
    if (!pinned.trim()) return { accept: false, reason: 'empty pinned tests' };
    const url = pathToFileURL(path.resolve(submissionFile)).href;
    const runnerFile = path.join(referenceDir, '_gate_runner.mjs');
    const prefix = [
      "import assert from 'node:assert/strict';",
      'const failures = [];',
      'function test(name, fn) {',
      '  try { fn(); } catch (e) { failures.push(String(name) + \': \' + (e && e.message ? e.message : String(e))); }',
      '}',
      'let dedupeSorted;',
      'try {',
      '  const mod = await import(' + JSON.stringify(url) + ');',
      '  dedupeSorted = mod.dedupeSorted;',
      '} catch (e) {',
      "  console.log(JSON.stringify({ok:false, reason:'import failed: ' + String(e)}));",
      '  process.exit(0);',
      '}',
      "if (typeof dedupeSorted !== 'function') {",
      "  console.log(JSON.stringify({ok:false, reason:'dedupeSorted not a function'}));",
      '  process.exit(0);',
      '}'
    ].join('\n');
    const suffix = [
      'if (failures.length) {',
      "  console.log(JSON.stringify({ok:false, reason:failures.join('; ')}));",
      '} else {',
      "  console.log(JSON.stringify({ok:true, reason:'all pinned tests passed'}));",
      '}'
    ].join('\n');
    fs.writeFileSync(runnerFile, prefix + '\n' + pinned + '\n' + suffix + '\n', 'utf8');
    const result = spawnSync(process.execPath, [runnerFile], { encoding: 'utf8', timeout: 25000, maxBuffer: 4194304 });
    if (result.error) return { accept: false, reason: 'spawn error: ' + String(result.error) };
    const out = String(result.stdout || '') + String(result.stderr || '');
    const lines = out.split('\n').map((l) => l.trim()).filter(Boolean);
    for (let i = lines.length - 1; i >= 0; i--) {
      try {
        const parsed = JSON.parse(lines[i]);
        if (typeof parsed.ok === 'boolean') {
          return { accept: parsed.ok, reason: String(parsed.reason || (parsed.ok ? 'passed' : 'failed')) };
        }
      } catch {}
    }
    return { accept: false, reason: 'runner failed: ' + out.slice(0, 400) };
  } catch (e) {
    return { accept: false, reason: 'gate exception: ' + String(e) };
  }
}

